def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script file not found: {script_path}")

    try:
        # Start the subprocess
        process = subprocess.Popen(['bash', script_path])
        parent_pid = process.pid

        cpu_usage = 0.0
        memory_usage = 0

        # Monitor the process
        start_time = time.time()
        while process.poll() is None:
            # Check if timeout has been reached
            if time.time() - start_time > timeout:
                process.terminate()
                try:
                    process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    process.kill()
                break

            try:
                # Get the process using psutil
                parent = psutil.Process(parent_pid)

                # Check if process is still alive and not a zombie
                if parent.is_running() and parent.status() != psutil.STATUS_ZOMBIE:
                    # Get CPU and memory usage
                    cpu_percent = parent.cpu_percent()
                    memory_info = parent.memory_info()

                    cpu_usage += cpu_percent
                    memory_usage += memory_info.rss
                else:
                    break

            except (psutil.NoSuchProcess, psutil.AccessDenied):
                break

            time.sleep(0.1)

        # Wait for process to complete if still running
        if process.poll() is None:
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                process.terminate()
                try:
                    process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    process.kill()

        return {
            'CPU Usage': cpu_usage,
            'Memory Usage': memory_usage
        }

    except Exception as e:
        # Ensure cleanup even on error
        try:
            process.terminate()
        except:
            pass
        raise e

